//! Authored provider projection tests. No provider, semantics or product writes.
use lightog_core::{common::canonical_hash as hash,provider_schema_v1 as compiler,semantic_review_v4};
use serde_json::{json,Value};
fn compile(schema:Value)->Value{compiler::execute("compile_qwen",&json!({"contract_version":compiler::VERSION,"name":"source_structure_review","schema":schema})).unwrap()}
#[test]fn strict_response_format_preserves_original_and_all_positive_constraints(){for schema in [semantic_review_v4::structure_output_schema(),semantic_review_v4::narrative_output_schema()]{let original=schema.clone();let result=compile(schema.clone());assert_eq!(schema,original);assert_eq!(result["full_schema_sha256"],hash(&original));let provider=&result["response_format"]["json_schema"]["schema"];assert_eq!(result["provider_schema_sha256"],hash(provider));assert_eq!(result["response_format"]["type"],"json_schema");assert_eq!(result["response_format"]["json_schema"]["strict"],true);assert_eq!(result["fallback_performed"],false);let local=&original["properties"]["reviews"]["items"]["properties"];let remote=&provider["properties"]["reviews"]["items"]["properties"];let path=if local.get("dimensions").is_some(){vec!["dimensions","properties","conditions"]}else{vec!["condition_exception_fidelity"]};let mut a=local;let mut b=remote;for k in path{a=&a[k];b=&b[k];}assert_eq!(a["allOf"],b["allOf"]);assert_eq!(b["allOf"][0]["then"]["properties"]["evidence_ids"]["minItems"],1);assert!(a["properties"]["evidence_ids"].get("uniqueItems").is_some());assert!(b["properties"]["evidence_ids"].get("uniqueItems").is_none());let mut receipt=result.clone();receipt.as_object_mut().unwrap().remove("receipt_sha256");assert_eq!(result["receipt_sha256"],hash(&receipt));}}
#[test]fn schema_locations_are_distinct_from_field_names_and_opaque_instance_data(){let schema=json!({"type":"object","properties":{"uniqueItems":{"type":"array","uniqueItems":true,"items":{"type":"object","properties":{"uniqueItems":{"type":"string"}}},"enum":[[{"uniqueItems":true,"multipleOf":3}]],"default":[{"uniqueItems":false}],"examples":[[{"uniqueItems":true}]]},"a/b~c":{"type":"array","uniqueItems":false,"items":{"type":"string"}}},"required":["uniqueItems"],"const":{"uniqueItems":["text"],"allOf":[{"uniqueItems":true}]}});let r=compile(schema.clone());let p=&r["response_format"]["json_schema"]["schema"];assert!(p["properties"].get("uniqueItems").is_some());assert_eq!(p["properties"]["uniqueItems"]["items"],schema["properties"]["uniqueItems"]["items"]);for key in ["enum","default","examples"]{assert_eq!(p["properties"]["uniqueItems"][key],schema["properties"]["uniqueItems"][key]);}assert_eq!(p["const"],schema["const"]);assert_eq!(p["required"],schema["required"]);assert_eq!(r["omission_paths"],json!(["/properties/a~1b~0c/uniqueItems","/properties/uniqueItems/uniqueItems"]));assert_eq!(r["omissions"][0]["value"],false);assert_eq!(r["omissions"][1]["value"],true);}
#[test]fn all_schema_bearing_containers_and_valid_local_references_are_walked(){let schema=json!({"type":"object","$defs":{"uniqueItems":{"type":"array","uniqueItems":true,"items":{"type":"string"}}},"properties":{"x":{"$ref":"#/$defs/uniqueItems"}},"allOf":[{"if":{"properties":{"x":{"type":"array","uniqueItems":true}}},"then":{"properties":{"x":{"minItems":1}}},"else":{"not":{"const":null}}}],"dependentSchemas":{"x":{"properties":{"x":{"type":"array","uniqueItems":true}}}},"additionalProperties":false,"unevaluatedProperties":false});let r=compile(schema.clone());assert_eq!(r["omission_paths"],json!(["/$defs/uniqueItems/uniqueItems","/allOf/0/if/properties/x/uniqueItems","/dependentSchemas/x/properties/x/uniqueItems"]));let p=&r["response_format"]["json_schema"]["schema"];assert_eq!(p["properties"]["x"]["$ref"],schema["properties"]["x"]["$ref"]);assert_eq!(p["allOf"][0]["then"],schema["allOf"][0]["then"]);assert_eq!(p["additionalProperties"],false);}
#[test]fn other_unsupported_or_unknown_keywords_fail_closed(){for key in ["multipleOf","contains","minContains","maxContains","additionalItems","patternProperties","propertyNames","unrecognizedConstraint"]{let mut schema=json!({"type":"array"});schema[key]=json!(1);let e=compiler::execute("compile_qwen",&json!({"contract_version":compiler::VERSION,"name":"x","schema":schema})).unwrap_err();assert!(e.code=="PROVIDER_SCHEMA_UNSUPPORTED_KEYWORD"||e.code=="PROVIDER_SCHEMA_UNKNOWN_KEYWORD");assert_eq!(e.details.unwrap()["schema_path"],format!("/{key}"));}}
#[test]fn bad_keyword_types_and_nonlocal_or_non_schema_refs_are_not_silently_sent(){for schema in [json!({"type":"array","uniqueItems":"true"}),json!({"type":"array","minItems":-1}),json!({"type":["string","string"]}),json!({"$ref":"https://example.invalid/ignored.json"}),json!({"$ref":"#/$defs/missing","$defs":{}}),json!({"$ref":"#/default","default":{"type":"array","uniqueItems":true}}),json!({"$ref":"#/enum/0","enum":[{"uniqueItems":true}]})]{assert!(compiler::execute("compile_qwen",&json!({"contract_version":compiler::VERSION,"name":"x","schema":schema})).is_err());}}
#[test]fn provider_can_allow_duplicates_but_complete_local_schema_still_rejects(){let schema=json!({"type":"array","items":{"type":"string"},"uniqueItems":true,"minItems":1});let r=compile(schema.clone());let provider=&r["response_format"]["json_schema"]["schema"];let duplicate=json!(["evidence_a","evidence_a"]);assert!(!jsonschema::validator_for(&schema).unwrap().is_valid(&duplicate));assert!(jsonschema::validator_for(provider).unwrap().is_valid(&duplicate));assert!(jsonschema::validator_for(provider).unwrap().is_valid(&json!(["evidence_a"])));assert!(!jsonschema::validator_for(provider).unwrap().is_valid(&json!([])));assert_eq!(r["local_validation_required"],true);assert_eq!(r["local_validation_performed"],false);}
#[test]fn name_and_operation_are_bounded_and_never_fallback_to_json_object(){for name in ["","bad name","日本語","foo.bar"]{assert!(compiler::execute("compile_qwen",&json!({"contract_version":compiler::VERSION,"name":name,"schema":{"type":"object"}})).is_err());}assert!(compiler::execute("compile_qwen",&json!({"contract_version":compiler::VERSION,"name":"x".repeat(65),"schema":{}})).is_err());assert!(compiler::execute("json_object",&json!({})).is_err());assert!(compiler::execute("compile_qwen",&json!({"contract_version":compiler::VERSION,"name":"x","schema":{},"strict":false})).is_err());}
